<script setup lang="ts">
import {onMounted,ref} from 'vue'
import SupportMissionPanel,{type Mission} from '@/components/SupportMissionPanel.vue'
import AppModal from '@/components/AppModal.vue'
import {demoMode,request} from '@/services/quality'
interface Intake {mission?:Mission|null;id:number;reference:string;title:string;description:string;contact:string;theme:string|null;availability:string|null;urgency:string;officine_name:string;version:number;qualification:string|null;qualification_note:string|null}
const rows=ref<Intake[]>([]),selected=ref<Intake|null>(null)
const loading=ref(false),busy=ref(false),allowed=ref(false),detail=ref(false),qualifying=ref(false)
const error=ref(''),notice=ref(''),search=ref(''),page=ref(1),last=ref(1),outcome=ref('ready'),note=ref('')
const labels:Record<string,string>={ready:'Prête pour une proposition',needs_information:'Informations complémentaires nécessaires',not_retained:'Non retenue à ce stade'}
async function load(){loading.value=true;error.value='';try{const d=await request<{data:Intake[];last_page:number}>('/support/intake?'+new URLSearchParams({page:String(page.value),search:search.value}));rows.value=d.data;last.value=d.last_page;allowed.value=true}catch(e){rows.value=[];allowed.value=false;error.value=(e as Error).message}finally{loading.value=false}}
function qualify(){outcome.value=selected.value?.qualification||'ready';note.value=selected.value?.qualification_note||'';error.value='';qualifying.value=true}
async function save(){busy.value=true;error.value='';try{await request(`/support/intake/${selected.value!.id}/qualify`,'POST',{version:selected.value!.version,qualification:outcome.value,note:note.value});qualifying.value=false;detail.value=false;notice.value='Qualification enregistrée. Aucune mission démarrée ni accès accordé.';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(()=>{if(!demoMode)load()})
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">MODULE 02 · GUICHET CENTRAL BEG</p><h1>Qualification des demandes</h1><p class="page-subtitle">Demandes soumises par les officines actives · coordination avec MFA.</p></div><button v-if="!demoMode" class="button secondary" :disabled="loading||busy" @click="load">Actualiser</button></div><div v-if="demoMode" class="panel form-body"><p>Le guichet central utilise l’API. Ouvrez l’aperçu connecté avec un compte coordinateur habilité et MFA.</p><RouterLink to="/dashboard/accompagnement" class="button secondary">Voir la démonstration M2</RouterLink></div><template v-else><p v-if="error&&!qualifying" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success" role="status">{{notice}}</p><div v-if="allowed" class="panel"><form class="table-toolbar" @submit.prevent="page=1;load()"><label class="search-field"><input v-model="search" aria-label="Rechercher au guichet" maxlength="180" placeholder="Officine, référence ou intitulé…"/></label><button class="button secondary" :disabled="loading||busy">Rechercher</button></form><p v-if="loading" role="status" class="form-body">Chargement…</p><div v-else class="table-scroll"><table><thead><tr><th>DEMANDE</th><th>OFFICINE</th><th>QUALIFICATION</th><th>ACTION</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.title}}<span class="table-subtitle">{{r.reference}} · v{{r.version}}</span></td><td>{{r.officine_name}}</td><td>{{r.qualification?labels[r.qualification]:'À qualifier'}}</td><td><button class="button secondary small" @click="selected=r;detail=true;error=''">Voir la demande</button></td></tr><tr v-if="!rows.length"><td colspan="4" class="empty-state">Aucune demande soumise visible pour ces critères.</td></tr></tbody></table></div><div class="panel-heading"><button class="button secondary" :disabled="loading||page<=1" @click="page--;load()">Précédent</button><span>{{page}} / {{last}}</span><button class="button secondary" :disabled="loading||page>=last" @click="page++;load()">Suivant</button></div></div><p class="module-disclaimer">Les brouillons, demandes retirées et officines suspendues ne sont pas consultables ici. Qualifier ne démarre pas une mission. L’accord explicite de l’officine sera requis ; les accès aux données restent approuvés séparément. La note de qualification est visible à l’officine.</p></template>
<AppModal v-model="detail" title="Consulter la demande" size="wide"><dl v-if="selected" class="form-body application-summary"><dt>Officine</dt><dd>{{selected.officine_name}}</dd><dt>Référence</dt><dd>{{selected.reference}}</dd><dt>Intitulé</dt><dd>{{selected.title}}</dd><dt>Besoin déclaré</dt><dd style="white-space:pre-wrap">{{selected.description}}</dd><dt>Contact</dt><dd>{{selected.contact}}</dd><dt>Thème</dt><dd>{{selected.theme||'Non précisé'}}</dd><dt>Disponibilité</dt><dd>{{selected.availability||'À convenir'}}</dd><dt>Urgence déclarée</dt><dd>{{selected.urgency}} — aucun délai garanti</dd><dt>Qualification</dt><dd>{{selected.qualification?labels[selected.qualification]:'À qualifier'}}</dd><dt>Note partagée</dt><dd style="white-space:pre-wrap">{{selected.qualification_note||'—'}}</dd></dl><SupportMissionPanel v-if="selected" :request-id="selected.id" :request-version="selected.version" :mission="selected.mission" coordinator :ready="selected.qualification==='ready'" submitted @saved="detail=false;notice='Proposition transmise. Accord de l’officine requis.';load()"/><template #footer><button class="button secondary" @click="detail=false">Fermer</button><button v-if="!selected?.mission" class="button primary" @click="qualify">Qualifier</button></template></AppModal>
<AppModal v-model="qualifying" title="Confirmer la qualification" :busy="busy"><form id="intake-qualification" class="form-body correction-form" @submit.prevent="save"><p v-if="error" class="alert error" role="alert">{{error}}</p><label>Résultat de qualification<select v-model="outcome" required><option v-for="(label,value) in labels" :key="value" :value="value">{{label}}</option></select></label><label>Note partagée avec l’officine<textarea v-model="note" required maxlength="3000" rows="5"/></label><p>Cette décision ne crée ni mission ni autorisation d’accès aux autres données de l’officine.</p></form><template #footer><button class="button secondary" :disabled="busy" @click="qualifying=false">Annuler</button><button class="button primary" :disabled="busy" type="submit" form="intake-qualification">Confirmer la qualification</button></template></AppModal></section></template>
